class TableInfo { const TableInfo(this.name,this.note,this.entry,this.players,this.status); final String name,note,players,status; final int entry; }
const tables=[TableInfo('Neon Knockout','Fast cards. Big energy.',100,'4 / 6 players','LIVE'),TableInfo('Midnight Royals','For the bold after dark.',250,'5 / 6 players','LIVE'),TableInfo('Ace Society','A premium table is waiting.',500,'3 / 6 players','WAITING')];

class TeenPattiApp extends StatefulWidget { const TeenPattiApp({super.key}); @override State<TeenPattiApp> createState()=>_TeenPattiAppState(); }
class _TeenPattiAppState extends State<TeenPattiApp>{
 bool logged=false; String name='Yash'; int credits=2450, tab=0; final history=<String>['Neon Knockout - Won ₹360','Midnight Royals - Folded']; final activities=<String>['Welcome game credits  +₹2,000','Joined Neon Knockout  -₹100','Won Neon Knockout  +₹360'];
 @override Widget build(BuildContext context)=>MaterialApp(debugShowCheckedModeBanner:false,theme:ThemeData(useMaterial3:true,brightness:Brightness.dark,scaffoldBackgroundColor:navy,colorScheme:ColorScheme.fromSeed(seedColor:violet,brightness:Brightness.dark)),home:logged?_home():Login(onDone:(v)=>setState(()=>{name=v,logged=true}))); 
 Widget _home(){ final pages=[_dashboard(),_lobby(),_wallet(),_profile()]; return Scaffold(appBar:AppBar(backgroundColor:navy,title:Text(['Home','Game Lobby','Wallet','Profile'][tab]),actions:[TextButton.icon(onPressed:()=>setState(()=>tab=2),icon:const Icon(Icons.account_balance_wallet,color:aqua),label:Text('₹$credits',style:const TextStyle(color:Colors.white))),IconButton(onPressed:_notifications,icon:const Icon(Icons.notifications_none,color:aqua))]),body:pages[tab],bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),label:'Home'),NavigationDestination(icon:Icon(Icons.casino_outlined),label:'Lobby'),NavigationDestination(icon:Icon(Icons.account_balance_wallet_outlined),label:'Wallet'),NavigationDestination(icon:Icon(Icons.person_outline),label:'Profile')])); }
 Widget _dashboard()=>ListView(padding:const EdgeInsets.all(18),children:[Card(child:ListTile(leading:const Icon(Icons.campaign_outlined,color:aqua),title:const Text('Weekend tables are live'),subtitle:const Text('New low-stakes and private sessions are available.'),onTap:_notifications)),const SizedBox(height:14),Container(padding:const EdgeInsets.all(24),decoration:BoxDecoration(gradient:const LinearGradient(colors:[Color(0xff382178),Color(0xff893cb4)]),borderRadius:BorderRadius.circular(22)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('LIVE TABLES NOW OPEN',style:TextStyle(fontSize:10,letterSpacing:1.2)),const SizedBox(height:10),Text('Ready for a good hand, $name?',style:const TextStyle(fontSize:27,fontWeight:FontWeight.bold)),const SizedBox(height:14),FilledButton(onPressed:()=>setState(()=>tab=1),child:const Text('Find a table'))])),const SizedBox(height:25),const Text('Featured games',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),...tables.map(_tableCard),const SizedBox(height:18),const Text('Game categories',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const Wrap(spacing:8,children:[Chip(label:Text('Classic Teen Patti')),Chip(label:Text('Quick play')),Chip(label:Text('Private sessions'))])]);
