 void _details(TableInfo t)=>showModalBottomSheet(context:context,backgroundColor:panel,builder:(c)=>Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[Text(t.name,style:const TextStyle(fontSize:25,fontWeight:FontWeight.bold)),const SizedBox(height:10),Text(t.note),const Divider(height:28),const Text('Entry requirement'),Text('₹${t.entry} credits',style:const TextStyle(color:aqua)),const SizedBox(height:12),const Text('Rules'),const Text('Three cards. Play blind or seen. Highest valid hand wins.'),const SizedBox(height:12),const Text('Game session'),const Text('Up to 6 players. 60-second turns. Raise, call, show or fold.'),const SizedBox(height:20),FilledButton(onPressed:(){Navigator.pop(c);_join(t);},child:const SizedBox(width:double.infinity,child:Text('Join game session',textAlign:TextAlign.center)))])));
