 void _payment(){final ref=TextEditingController();showModalBottomSheet(context:context,backgroundColor:panel,isScrollControlled:true,builder:(c)=>Padding(padding:EdgeInsets.fromLTRB(24,24,24,MediaQuery.of(c).viewInsets.bottom+24),child:Column(mainAxisSize:MainAxisSize.min,children:[const Text('Scanner / QR payment',style:TextStyle(fontSize:23,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('Scan with your preferred payment app. No Razorpay or payment gateway is included.'),const SizedBox(height:18),Container(width:150,height:150,color:Colors.white,child:GridView.count(crossAxisCount:10,physics:const NeverScrollableScrollPhysics(),children:List.generate(100,(i)=>Container(margin:const EdgeInsets.all(1),color:(i*7)%11<5?Colors.black:Colors.white))),const SizedBox(height:16),TextField(controller:ref,decoration:const InputDecoration(labelText:'Payment reference',border:OutlineInputBorder())),const SizedBox(height:12),FilledButton(onPressed:(){setState(()=>activities.insert(0,'Payment reference submitted - Pending verification'));Navigator.pop(c);_msg('Reference submitted for verification.');},child:const Text('Submit for verification'))])));}
 Widget _profile()=>ListView(padding:const EdgeInsets.all(18),children:[Card(color:panel,child:ListTile(leading:CircleAvatar(radius:28,child:Text(name[0].toUpperCase())),title:Text(name,style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold)),subtitle:const Text('Profile and account settings'),trailing:IconButton(onPressed:_editName,icon:const Icon(Icons.edit_outlined)))),const SizedBox(height:20),const Text('Game history',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),...history.map((e)=>Card(color:panel,child:ListTile(leading:const Icon(Icons.emoji_events_outlined,color:aqua),title:Text(e)))),OutlinedButton.icon(onPressed:_support,icon:const Icon(Icons.support_agent),label:const Text('Help / FAQ / report issue'))]);
 void _editName(){final c=TextEditingController(text:name);showDialog(context:context,builder:(x)=>AlertDialog(title:const Text('Profile details'),content:TextField(controller:c,decoration:const InputDecoration(labelText:'Display name')),actions:[TextButton(onPressed:()=>Navigator.pop(x),child:const Text('Cancel')),FilledButton(onPressed:(){setState(()=>name=c.text);Navigator.pop(x);},child:const Text('Save'))]));}
 void _support(){final c=TextEditingController();showDialog(context:context,builder:(x)=>AlertDialog(title:const Text('Help & support'),content:Column(mainAxisSize:MainAxisSize.min,children:[const Text('FAQ: Join a table from the lobby. QR payment references require verification.'),const SizedBox(height:12),TextField(controller:c,maxLines:3,decoration:const InputDecoration(labelText:'Report an issue',border:OutlineInputBorder()))]),actions:[FilledButton(onPressed:(){Navigator.pop(x);_msg('Issue report saved locally.');},child:const Text('Submit'))]));}
