}

class Login extends StatefulWidget{const Login({super.key,required this.onDone});final ValueChanged<String> onDone;@override State<Login> createState()=>_LoginState();}
class _LoginState extends State<Login>{final id=TextEditingController(),name=TextEditingController(text:'Yash'),otp=TextEditingController();bool sent=false;@override Widget build(BuildContext c)=>Scaffold(body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(26),child:Card(color:panel,child:Padding(padding:const EdgeInsets.all(24),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('teen patti',style:TextStyle(fontSize:28,fontWeight:FontWeight.bold,color:aqua)),const SizedBox(height:24),const Text('Sign in or create profile',style:TextStyle(fontSize:25,fontWeight:FontWeight.bold)),const Text('Mobile/email and OTP are UI-only in this prototype.'),const SizedBox(height:16),TextField(controller:id,decoration:const InputDecoration(labelText:'Mobile number or email',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:name,decoration:const InputDecoration(labelText:'Display name',border:OutlineInputBorder())),const SizedBox(height:12),if(!sent)FilledButton(onPressed:(){if(id.text.isNotEmpty)setState(()=>sent=true);},child:const Text('Continue with OTP'))else Column(children:[TextField(controller:otp,decoration:const InputDecoration(labelText:'Demo OTP: 123456',border:OutlineInputBorder())),const SizedBox(height:12),FilledButton(onPressed:(){if(otp.text=='123456')widget.onDone(name.text.isEmpty?'Player':name.text);},child:const Text('Verify and enter'))])]))))));}
class GameSession extends StatefulWidget{const GameSession({super.key,required this.table,required this.name,required this.onFinish});final TableInfo table;final String name;final void Function(bool,int) onFinish;@override State<GameSession> createState()=>_GameSessionState();}
class _GameSessionState extends State<GameSession>{late Timer timer;int seconds=60,pot=450;bool seen=false,done=false;@override void initState(){super.initState();timer=Timer.periodic(const Duration(seconds:1),(_){if(mounted)setState(()=>seconds=seconds==0?60:seconds-1);});}@override void dispose(){timer.cancel();super.dispose();}void end(bool won){if(done)return;setState(()=>done=true);widget.onFinish(won,won?(pot*1.6).round():0);showDialog(context:context,barrierDismissible:false,builder:(c)=>AlertDialog(title:Text(won?'You won!':'Hand folded'),content:Text(won?'Result added to your local game credits.':'Result saved to game history.'),actions:[FilledButton(onPressed:()=>Navigator.of(c).popUntil((r)=>r.isFirst),child:const Text('Back to lobby'))]));}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text('${widget.table.name}  00:${seconds.toString().padLeft(2,'0')}')),body:Padding(padding:const EdgeInsets.all(18),child:Column(children:[Expanded(child:Container(width:double.infinity,decoration:BoxDecoration(color:const Color(0xff15345a),borderRadius:BorderRadius.circular(140),border:Border.all(color:violet,width:9)),child:Center(child:Column(mainAxisSize:MainAxisSize.min,children:[const Text('THE POT'),Text('₹$pot',style:const TextStyle(fontSize:32,fontWeight:FontWeight.bold)),const Icon(Icons.workspace_premium,color:Colors.amber),const SizedBox(height:25),Text(seen?'A♥  A♦  K♥':'?  ?  ?',style:const TextStyle(fontSize:28,color:Colors.white))])))),const SizedBox(height:12),Text(seen?'Cards seen. Call, raise or show.':'Your turn: blind or see cards.'),Wrap(spacing:8,children:[OutlinedButton(onPressed:()=>end(false),child:const Text('Fold')),OutlinedButton(onPressed:seen?null:()=>setState(()=>seen=true),child:const Text('See cards')),FilledButton.tonal(onPressed:()=>setState(()=>pot+=seen?200:100),child:Text(seen?'Call ₹100':'Blind ₹50')),FilledButton(onPressed:()=>seen?end(true):setState(()=>pot+=300),child:Text(seen?'Show cards':'Raise'))])])));}
